const decoder = new TextDecoder();
const entered = Promise.withResolvers<void>();
const release = Promise.withResolvers<void>();
let held = false;
let endRequests = 0;
const snapshots: { rootTranscript: string; raw: string }[] = [];
const server = Bun.serve({ hostname: "127.0.0.1", port: 0, idleTimeout: 0, async fetch(request) {
 const url = new URL(request.url);
 if (url.pathname === "/hold") { held = true; entered.resolve(); await release.promise; held = false; return new Response("released"); }
 if (url.pathname === "/await-held") { await entered.promise; return new Response("held"); }
 if (url.pathname === "/release") { release.resolve(); return new Response("released"); }
 if (url.pathname === "/observations") return Response.json({ held, endRequests, snapshots });
 const body = request.method === "GET" || request.method === "HEAD" ? undefined : new Uint8Array(await request.arrayBuffer());
 if (request.method === "POST" && url.pathname.endsWith("/end")) {
  endRequests++;
  const rootTranscript = (await Bun.file("/tmp/soroi254-runtime/root-path.txt").text()).trim();
  snapshots.push({ rootTranscript, raw: await Bun.file(rootTranscript).text() });
 }
 const headers = new Headers(request.headers); headers.delete("host");
 const response = await fetch(new URL(url.pathname + url.search, "http://127.0.0.1:19688"), { method: request.method, headers, body });
 const bytes = new Uint8Array(await response.arrayBuffer());
 const text = decoder.decode(bytes);
 const sent: unknown = body?.length ? JSON.parse(decoder.decode(body)) : null;
 const observed: unknown = text ? JSON.parse(text) : null;
 const row = { method: request.method, path: url.pathname + url.search, request: sent, status: response.status, response: observed, held, endRequests };
 await appendFile("/tmp/soroi254-runtime/http.jsonl", JSON.stringify(row) + "\n");
 if (request.method !== "GET") console.log(JSON.stringify(row));
 return new Response(bytes.length ? bytes : null, { status: response.status, headers: response.headers });
} });
console.log(`root transcript observer ${server.url} -> http://127.0.0.1:19688`);
process.once("SIGINT", async () => { release.resolve(); await server.stop(); process.exit(0); });
