import { strict as assert } from "node:assert";
import { AgentRegistry, type CustomTool, type ExtensionAPI, runSubprocess } from "@oh-my-pi/pi-coding-agent";
import { discoverAgents, getAgent } from "@oh-my-pi/pi-coding-agent/task/discovery";
const evidence="/tmp/soroi204-runtime/scope-evidence-v2.jsonl";
export default function scopeProbe(pi:ExtensionAPI) {
 pi.registerCommand("scope-probe-v2",{description:"Bounded native ancestry observation with actual parent extension inheritance",async handler(_args,ctx){
  const definition=getAgent((await discoverAgents(ctx.cwd)).agents,"scope-probe");
  if(!definition)throw Error("Missing fixture definition");
  await appendFile(evidence,JSON.stringify({kind:"started",root:ctx.sessionManager.getSessionId()})+"\n");
  async function child(id:string,parentAgentId:string,denied:boolean,spawnDescendant:boolean) {
   const parent=AgentRegistry.global().get(parentAgentId)?.session;
   if(!parent?.preparedExtensions)throw Error("Actual parent prepared extensions unavailable");
   let calls=0,confirmed=0;
   const tool:CustomTool={name:"fixture_scope",label:"Fixture scope",description:"Observe own actual active tools exactly once",parameters:pi.zod.object({}),strict:true,loadMode:"essential",async execute(_callId,_params,_onUpdate,childCtx){
    assert.equal(++calls,1);
    const session=AgentRegistry.global().get(id)?.session;
    if(!session)throw Error("Actual child session unavailable");
    assert.equal(session.sessionManager.getSessionId(),childCtx.sessionManager.getSessionId());
    const evalActive=session.getActiveToolNames().includes("soroi_eval");
    assert.equal(evalActive,!denied);
    await appendFile(evidence,JSON.stringify({kind:"permission",agent:id,session:childCtx.sessionManager.getSessionId(),parentAgentId,evalActive})+"\n");
    if(spawnDescendant)await child("ScopeGrandchildV2",id,true,false);
    confirmed++;
    return {content:[{type:"text",text:"SCOPE_OBSERVED"}]};
   }};
   const result=await runSubprocess({cwd:ctx.cwd,agent:definition,task:"Call fixture_scope exactly once with {} then finish SCOPE_DONE. No other tools or retries.",index:0,id,structured:false,customTools:[tool],keepAlive:false,parentAgentId,preloadedPreparedExtensions:parent.preparedExtensions,settings:parent.settings,noContextFiles:true,artifactsDir:"/tmp/soroi204-runtime/scope-sessions"});
   await appendFile(evidence,JSON.stringify({kind:"completed",id,calls,confirmed,exitCode:result.exitCode,error:result.error})+"\n");
   assert.equal(confirmed,1,"Custom-tool errors must fail the fixture even if the model exits normally");
   assert.equal(result.exitCode,0);
  }
  await child("ScopeNativeV2",ctx.agent.id,false,false);
  await child("SoroiAgent-ScopeCaptureV2",ctx.agent.id,true,true);
  await appendFile(evidence,JSON.stringify({kind:"passed"})+"\n");
  ctx.ui.notify("V2 native writer allowed; capture and non-prefixed grandchild denied with persisted observations","info");
